+type Status = "open" | "done";
+
+type Task = {
+  id: number;
+  title: string;
+  tags: string[];
+  status: Status;
+  createdAt: string;
+  due?: string;
+  completedAt?: string;
+};
+
+type Database = { tasks: Task[]; nextId: number };
+
+const file = Bun.env.TASKBOARD_FILE || `${process.cwd()}/.taskboard.json`;
+
+function fail(message: string): never {
+  console.error(message);
+  process.exit(1);
+}
+
+function isDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const [year, month, day] = value.split("-").map(Number);
+  const date = new Date(year, month - 1, day);
+  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
+}
+
+function today(): string {
+  const now = new Date();
+  const offset = now.getTimezoneOffset() * 60_000;
+  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
+}
+
+function load(): Database {
+  if (!Bun.file(file).size) return { tasks: [], nextId: 1 };
+  let value: unknown;
+  try {
+    value = JSON.parse(Bun.file(file).text ? "" : "");
+  } catch {
+    // Re-read synchronously below because Bun.file().text() is asynchronous.
+  }
+  try {
+    value = JSON.parse(require("fs").readFileSync(file, "utf8"));
+  } catch {
+    fail("Malformed taskboard database");
+  }
+  if (!value || typeof value !== "object") fail("Malformed taskboard database");
+  const db = value as Partial<Database>;
+  if (!Array.isArray(db.tasks) || !Number.isSafeInteger(db.nextId) || db.nextId < 1) {
+    fail("Malformed taskboard database");
+  }
+  for (const task of db.tasks) {
+    if (!task || !Number.isSafeInteger(task.id) || typeof task.title !== "string" ||
+      !Array.isArray(task.tags) || (task.status !== "open" && task.status !== "done") ||
+      typeof task.createdAt !== "string" || (task.due !== undefined && !isDate(task.due))) {
+      fail("Malformed taskboard database");
+    }
+  }
+  return db as Database;
+}
+
+function save(db: Database): void {
+  const temp = `${file}.${process.pid}.${Date.now()}.tmp`;
+  try {
+    require("fs").writeFileSync(temp, `${JSON.stringify(db, null, 2)}\n`);
+    require("fs").renameSync(temp, file);
+  } catch {
+    try { require("fs").unlinkSync(temp); } catch {}
+    fail("Unable to write taskboard database");
+  }
+}
+
+function options(args: string[], allowed: string[]): Record<string, string> {
+  const result: Record<string, string> = {};
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!allowed.includes(flag) || value === undefined || result[flag] !== undefined) fail("Invalid command arguments");
+    result[flag] = value;
+  }
+  return result;
+}
+
+function taskId(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value)) fail("Task ID must be a positive integer");
+  const id = Number(value);
+  if (!Number.isSafeInteger(id) || id < 1) fail("Task ID must be a positive integer");
+  return id;
+}
+
+const [command, ...args] = Bun.argv.slice(2);
+let output: unknown;
+
+switch (command) {
+  case "add": {
+    const opts = options(args, ["--title", "--tags", "--due"]);
+    const title = opts["--title"]?.trim();
+    if (!title) fail("Title must not be empty");
+    if (opts["--due"] && !isDate(opts["--due"])) fail("Due date must be YYYY-MM-DD");
+    const tags = [...new Set((opts["--tags"] || "").split(",").map(tag => tag.trim().toLowerCase()).filter(Boolean))];
+    const db = load();
+    const task: Task = { id: db.nextId++, title, tags, status: "open", createdAt: new Date().toISOString() };
+    if (opts["--due"]) task.due = opts["--due"];
+    db.tasks.push(task);
+    save(db);
+    output = task;
+    break;
+  }
+  case "list": {
+    const opts = options(args, ["--status", "--tag", "--overdue"]);
+    if (opts["--status"] && opts["--status"] !== "open" && opts["--status"] !== "done") fail("Status must be open or done");
+    if (opts["--overdue"] && !isDate(opts["--overdue"])) fail("Overdue date must be YYYY-MM-DD");
+    output = load().tasks.filter(task =>
+      (!opts["--status"] || task.status === opts["--status"]) &&
+      (!opts["--tag"] || task.tags.includes(opts["--tag"].trim().toLowerCase())) &&
+      (!opts["--overdue"] || (task.status === "open" && !!task.due && task.due < opts["--overdue"]))
+    ).sort((a, b) => a.id - b.id);
+    break;
+  }
+  case "done": {
+    if (args.length !== 1) fail("Usage: done ID");
+    const db = load();
+    const task = db.tasks.find(item => item.id === taskId(args[0]));
+    if (!task) fail("Task not found");
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      save(db);
+    }
+    output = task;
+    break;
+  }
+  case "delete": {
+    if (args.length !== 1) fail("Usage: delete ID");
+    const db = load();
+    const id = taskId(args[0]);
+    const index = db.tasks.findIndex(task => task.id === id);
+    if (index < 0) fail("Task not found");
+    const [task] = db.tasks.splice(index, 1);
+    save(db);
+    output = task;
+    break;
+  }
+  case "stats": {
+    if (args.length) fail("Usage: stats");
+    const tasks = load().tasks;
+    output = {
+      total: tasks.length,
+      open: tasks.filter(task => task.status === "open").length,
+      done: tasks.filter(task => task.status === "done").length,
+      overdue: tasks.filter(task => task.status === "open" && !!task.due && task.due < today()).length,
+    };
+    break;
+  }
+  default:
+    fail("Unknown command");
+}
+
+console.log(JSON.stringify(output));
