    if (opts["--due"]) task.due = opts["--due"];
    db.tasks.push(task);
    save(db);
    output = task;
    break;
  }
  case "list": {
    const opts = options(args, ["--status", "--tag", "--overdue"]);
    if (opts["--status"] && opts["--status"] !== "open" && opts["--status"] !== "done") fail("Status must be open or done");
    if (opts["--overdue"] && !isDate(opts["--overdue"])) fail("Overdue date must be YYYY-MM-DD");
    output = load().tasks.filter(task =>
      (!opts["--status"] || task.status === opts["--status"]) &&
      (!opts["--tag"] || task.tags.includes(opts["--tag"].trim().toLowerCase())) &&
      (!opts["--overdue"] || (task.status === "open" && !!task.due && task.due < opts["--overdue"]))
    ).sort((a, b) => a.id - b.id);
    break;
  }
  case "done": {
    if (args.length !== 1) fail("Usage: done ID");
    const db = load();
    const task = db.tasks.find(item => item.id === taskId(args[0]));
    if (!task) fail("Task not found");
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      save(db);
    }
    output = task;
    break;
  }
  case "delete": {
    if (args.length !== 1) fail("Usage: delete ID");
    const db = load();
    const id = taskId(args[0]);
    const index = db.tasks.findIndex(task => task.id === id);
    if (index < 0) fail("Task not found");
    const [task] = db.tasks.splice(index, 1);
    save(db);
    output = task;
    break;
  }
